    private void minesField(Inventory i,Player p){String id=selectedMinesFields.get(p.getUniqueId());var f=plugin.minesFieldManager.summary(id);if(f==null){i.setItem(22,item(Material.BARRIER,"Field no longer exists"));back(i);return;}i.setItem(4,item(Material.TNT,f.name()+"  ["+f.id()+"]",pretty(f.style())+" • "+pretty(f.layout())+" • "+(f.playMode().equals("world")?"World play":"GUI play"),f.locationText()));i.setItem(10,item(Material.COMPASS,"Position","Move or rotate in 22.5° steps"));i.setItem(19,item(Material.ENDER_PEARL,"Move here","Place the field three blocks in front of you."));i.setItem(20,item(Material.ARROW,"Rotate left","Turn 22.5° left"));i.setItem(21,item(Material.ARROW,"Rotate right","Turn 22.5° right"));i.setItem(12,item(Material.COMPARATOR,"Field settings","Layout and play mode"));i.setItem(28,state(f.layout().equals("horizontal"),"Horizontal","Tabletop layout"));i.setItem(30,state(f.layout().equals("vertical"),"Vertical","Upright layout"));i.setItem(32,state(f.playMode().equals("gui"),"GUI play","Clicking opens the inventory game"));i.setItem(34,state(f.playMode().equals("world"),"World play","Reveal tiles directly on the physical field"));i.setItem(14,item(Material.PAINTING,"Appearance","Choose the field style"));int[] slots={37,39,41,43};Material[] icons={Material.DARK_OAK_PLANKS,Material.IRON_BLOCK,Material.AMETHYST_BLOCK,Material.SMOOTH_QUARTZ};int n=0;for(String style:plugin.minesFieldManager.styles()){i.setItem(slots[n],item(icons[n],pretty(style),f.style().equals(style)?"Current style":"Click to apply"));n++;}i.setItem(16,item(Material.BARRIER,"Danger zone","Permanent field actions"));i.setItem(25,item(Material.LAVA_BUCKET,"Remove field","Requires a second click."));i.setItem(45,item(Material.ARROW,"Back to Mines fields"));}
    private void plinkoHome(Inventory i){i.setItem(20,item(Material.SLIME_BALL,"Manage boards","Browse and edit existing world Plinko boards."));i.setItem(24,item(Material.LIME_DYE,"Create board","Choose a model style for a new world board."));back(i);}
