    private void appearance(Inventory i){String current=plugin.getConfig().getString("websiteCustomization.theme","classic");for(int n=0;n<THEMES.length;n++)i.setItem(19+n,state(THEMES[n].equals(current),pretty(THEMES[n]),THEMES[n].equals(current)?"Selected":"Click to select"));boolean maintenance=plugin.getConfig().getBoolean("websiteCustomization.maintenance.enabled",false);i.setItem(31,state(!maintenance,"Maintenance mode",maintenance?"New games are paused":"Games are open","Click to toggle"));back(i);}
