    private void coinflipBoardClick(Player p,int slot){String id=selectedBoards.get(p.getUniqueId());if(id==null)return;if(slot==19)plugin.coinflipBoardManager.moveHere(p,id);else if(slot==21)plugin.coinflipBoardManager.rotateByDegrees(p,id,-22.5f);else if(slot==23)plugin.coinflipBoardManager.rotateByDegrees(p,id,22.5f);else if(slot==25){String key="board-remove:"+id;if(!key.equals(confirmations.remove(p.getUniqueId()))){confirmations.put(p.getUniqueId(),key);p.sendActionBar(Component.text("Click Remove board again to confirm.",NamedTextColor.YELLOW));return;}plugin.coinflipBoardManager.remove(p,id);selectedBoards.remove(p.getUniqueId());open(p,Page.COINFLIP_BOARDS);return;}else{String style=switch(slot){case 37->"street";case 39->"classic";case 41->"royal";case 43->"copper";default->null;};if(style!=null)plugin.coinflipBoardManager.changeStyle(p,id,style);}open(p,Page.COINFLIP_BOARD);}
    private void blackjackTablesClick(Player p,int slot){int[] slots={10,11,12,13,14,15,16,19,20,21,22,23,24,25,28,29,30,31,32,33,34};int n=index(slots,slot);var tables=plugin.blackjackTableManager.summaries();if(n>=0&&n<tables.size())openBlackjackTable(p,tables.get(n).id());}
